# %% ../nbs/01_data.ipynb #56d556e3-fb85-4669-934c-33f0d93fb142
def shift_no_wrap(x, shifts, dims):
    """Drop-in replacement for torch.roll with zero-fill instead of wrap."""
    if shifts == 0: return x
    out = torch.roll(x, shifts=shifts, dims=dims)
    n = abs(shifts)
    if shifts > 0: out.narrow(dims, 0, n).zero_()
    else: out.narrow(dims, out.size(dims)-n, n).zero_()
    return out

# %% ../nbs/01_data.ipynb #9cbee8f8-d8ff-4f74-882e-7dde4db4f684
def sample_shift(max_shift, sigma=7, size=None):
    "Samples shifts amounts as integers from a truncated normal distribution"
    a, b = -max_shift / sigma, max_shift / sigma
    samples = truncnorm.rvs(a, b, loc=0, scale=sigma, size=size)
    if size is None: return int(round(samples))
    return np.rint(samples).astype(int)

# %% ../nbs/01_data.ipynb #7250ec68-df48-486b-8b30-00b9df5cf2cf
def note_length_weights(img, min_weight=1.0, power=0.5):
  "note weight is inversely proportional to note length"
  weights = np.ones_like(img, dtype=np.float32)
  lengths = []
  for row in range(img.shape[0]):  # horizontal slices
      labeled, n = label(img[row] > 0)
      for i in range(1, n+1):
          run = (labeled == i)
          length = run.sum()
          lengths.append(length)
          weights[row, run] = (1.0 / length) ** power
  #return weights / weights.mean()  # normalize so mean weight = 1
  if lengths != []: 
      median_length = np.median(lengths)
      weights = weights * (median_length)**power  # normalize by median length
  return weights 

# %% ../nbs/01_data.ipynb #ea0fb421-49e9-4082-8081-e30300c5a213
class AnchorDataset(Dataset):
    "piano roll pair dataset"
    def __init__(self, 
            image_dataset_dir='~/datasets/POP909_images_basic/', 
            crop_size=(128,128),  # int for square of tuple for rectangle 
            split='train',
            val_fraction=0.1,
            seed=42,
            verbose=True,
            aug_y_max=12, # number of pitch semitones +/- for data augmentation
            sigma=7, # truncnorm tightness param for aug_y
            pad_x=(0,0), # (left, right) : crop wider to (crop_sizw-pad_x[0], crop_size+pad_x[1])
            ):
        self.crop_size, self.aug_y_max, self.sigma, self.pad_x = crop_size, aug_y_max, sigma, pad_x
        
        # Load and split filenames
        all_filenames = glob(os.path.join(os.path.expanduser(image_dataset_dir), '**/*.png'), recursive=True)
        rng = random.Random(seed)
        shuffled = all_filenames.copy()
        rng.shuffle(shuffled)
        split_idx = int(len(shuffled) * (1 - val_fraction))
        self.filenames = shuffled[:split_idx] if split == 'train' else shuffled[split_idx:]            
        self.actual_len = len(self.filenames)
        self.images, self.note_weights = [], []
        if verbose: print(f"Loading {self.actual_len} {split} files from {image_dataset_dir}... ",end="")
        for f in self.filenames: 
            img = Image.open(f).convert('L')  # grayscale
            img =  (np.array(img, dtype=np.uint8) > 0).astype(np.uint8) # binary uint8
            self.images.append(img)
            self.note_weights.append(note_length_weights(img).astype(np.float16)) # float16 saves system RAM, autocasts to bfloat16 later
        if verbose: print(f"Finished loading.")

    def __len__(self):
        return self.actual_len * 100  # arbitrary large number for epoch length

    def __getitem__(self, idx, pad_x=None, crop_size=None):
        if crop_size is None: crop_size = self.crop_size
        if isinstance(crop_size, int): crop_size = (crop_size, crop_size)
        if pad_x is None: pad_x = self.pad_x 

        # ignore idx, just randomly sample
        file_idx = random.randint(0, self.actual_len - 1)
        img = torch.from_numpy( self.images[file_idx] ).float()
        note_weights = torch.from_numpy(self.note_weights[file_idx])

        # augmentation in y: transpose entire img in y (pitch)
        aug_y = sample_shift( self.aug_y_max, self.sigma) 
        img = shift_no_wrap(img, shifts=aug_y, dims=0) # prevent low/high notes from wrapping
        note_weights = shift_no_wrap(note_weights, shifts=aug_y, dims=0) 
        
        # cropping in x 
        h, w = img.shape
        min_loc, max_loc = 0+pad_x[0], w - crop_size[1] - pad_x[1]
        loc = random.randint(min_loc, max_loc)      
        img = img[:, loc-pad_x[0]: loc + crop_size[1]+pad_x[1]]  # crop horizontally
        note_weights = note_weights[:, loc-pad_x[0]: loc + crop_size[1]+pad_x[1]]  # crop horizontally

        # optional: additional cropping in y: 
        if crop_size[0] < img.shape[0]: 
            mid, hc = img.shape[0]//2,  crop_size[0]//2
            img = img[mid-hc: mid+hc, :]
            note_weights = note_weights[mid-hc: mid+hc, :]

        return {
            'img': img.unsqueeze(0),  # add channel dim: (1, 128+pad_x[0], 128+pad_x[1])
            'file_idx': file_idx,
            'note_weights': note_weights.unsqueeze(0),
        }

# %% ../nbs/01_data.ipynb #9b1f47bb-c1cc-4a0a-a5f3-5083b91eca58
def sample_shifts(max_x, max_y, sigma):
    "Get X and Y shifts; one of them must be non-zero"
    while True:
        sx, sy = sample_shift(max_x, sigma), sample_shift(max_y, sigma)
        if sx != 0 or sy != 0: return sx, sy

# %% ../nbs/01_data.ipynb #a164c279
class PRPairDataset(Dataset):
    "piano roll pair dataset"
    def __init__(self, 
            image_dataset_dir='~/datasets/POP909_images_basic', 
            crop_size=128, 
            max_shift_x=12, 
            max_shift_y=12,
            split='train',
            val_fraction=0.1,
            seed=42,
            verbose=True,
            sigma=7,               # param for truncnorm dist for sampling shifts/deltas
            shared=None,   # Possible shared memory thing for changing deets on the fly
            ):
        self.crop_size, self.max_shift_x, self.max_shift_y = crop_size, max_shift_x, max_shift_y
        self.sigma, self.shared = sigma, shared
        
        # Load and split filenames
        all_filenames = glob(os.path.join(os.path.expanduser(image_dataset_dir), '**/*.png'), recursive=True)
        rng = random.Random(seed)
        shuffled = all_filenames.copy()
        rng.shuffle(shuffled)
        split_idx = int(len(shuffled) * (1 - val_fraction))
        
        if split == 'train':
            self.filenames = shuffled[:split_idx]
        else:
            self.filenames = shuffled[split_idx:]
            
        self.actual_len = len(self.filenames)
        self.images = []
        if verbose: print(f"Loading {self.actual_len} {split} files from {image_dataset_dir}... ",end="")
        for f in self.filenames: 
            img = Image.open(f).convert('L')  # grayscale
            self.images.append((np.array(img, dtype=np.uint8) > 0).astype(np.uint8)) # binary uint8
        if verbose: print(f"Finished loading.")

    def __len__(self):
        return self.actual_len * 100  # arbitrary large number for epoch length

    def __getitem__(self, idx):
        # ignore idx, just randomly sample
        file_idx = random.randint(0, self.actual_len - 1)
        img = torch.from_numpy(self.images[file_idx]).float() 

        # augmentation in y: transpose entire img in y before doing aything else.
        aug_y = sample_shift(6, self.sigma)    # +/- six semitones data augmentation (shift_y may add +/- 12 more, below)
        img = shift_no_wrap(img, shifts=aug_y, dims=0)
         
        h, w = img.shape
        msx = self.shared['training']['max_shift_x'] if self.shared else self.max_shift_x
        msy = self.shared['training']['max_shift_y'] if self.shared else self.max_shift_y
        shift_x, shift_y = sample_shifts(msx, msy, self.sigma)

        # cropping
        # sample loc1 such that both crops are valid
        min_loc = max(0, -shift_x)
        max_loc = min(w - self.crop_size, w - self.crop_size - shift_x)
        loc1 = random.randint(min_loc, max_loc)
        loc2 = loc1 + shift_x
        
        # crop horizontally
        img1 = img[:, loc1:loc1 + self.crop_size]  # img1 is a random crop (augmentation)
        img2 = img[:, loc2:loc2 + self.crop_size]  # img2, rather than being img1+shift, is just cropped from a slightly different locationb        
        img2 = shift_no_wrap(img2, shifts=shift_y, dims=0)    # y-shifts (transposition)
        
        return {
            'img1': img1.unsqueeze(0),  # add channel dim (1, 128, 128)
            'img2': img2.unsqueeze(0),
            'deltas': torch.tensor([shift_x, shift_y], dtype=torch.float32).abs(),
            'file_idx': file_idx,
        }

# %% ../nbs/01_data.ipynb #13ba9ffc-51c2-4b85-b357-4e1ea53e0a23
SCHEME_NAMES = {  0: 'pitch-pitch',    1: 'time-time',        2: 'pitch-time'}
TARGET_NAMES = {1.0: 'parallel',    -1.0: 'anti-parallel',  0.0: 'orthogonal'}

class ShiftedTripletDataset(AnchorDataset):
    """Piano roll triplet dataset inheriting from AnchorDataset."""
    def __init__(self, 
            max_shift_x=12, 
            max_shift_y=12,
            shared=None,
            aug_y_max=6, 
            **kwargs,   # passes through to AnchorDataset.__init__
            ):
        super().__init__(aug_y_max=aug_y_max, **kwargs)
        self.max_shift_x, self.max_shift_y = max_shift_x, max_shift_y
        self.shared = shared

    def __getitem__(self, idx, requested_scheme=None, requested_target=None):
        # --- sample shifts sx1, sy1, sx2, sy2 from distribution
        msx = self.shared['training']['max_shift_x'] if self.shared else self.max_shift_x
        msy = self.shared['training']['max_shift_y'] if self.shared else self.max_shift_y
        while True:
            scheme = torch.randint(0, 3, (1,)).item() if requested_scheme is None else int(requested_scheme)
            if requested_target is not None and requested_target != 0: scheme = torch.randint(0, 2, (1,)).item()
            sign1 = 1 if torch.rand(1) > 0.5 else -1
            if requested_target is None: 
                sign2 = 1 if torch.rand(1) > 0.5 else -1
            else: 
                sign2 = sign1 * int(requested_target)
            if scheme == 0:    
                s1 = abs(sample_shift(msy, self.sigma)) or 1  # 0's are handled explicitly below according to scheme
                s2 = abs(sample_shift(msy, self.sigma)) or 1
                dy1, dx1, dy2, dx2 = sign1*s1, 0, sign2*s2, 0    # both shift in y
            elif scheme == 1:  
                s1 = abs(sample_shift(msx, self.sigma)) or 1
                s2 = abs(sample_shift(msx, self.sigma)) or 1
                dy1, dx1, dy2, dx2 = 0, sign1*s1, 0, sign2*s2    # both shifts in x
            else:                                                
                s1 = abs(sample_shift(msy, self.sigma)) or 1
                s2 = abs(sample_shift(msx, self.sigma)) or 1
                dy1, dx1, dy2, dx2 = sign1*s1, 0, 0, sign2*s2 # first one y, second one x
            if not ((dy1==dy2) and (dx1==dx2)) and not (dx1==0 and dy1==0) and not (dx2==0 and dy2==0): break 
        target = float(np.sign(sign1 * sign2)) if scheme < 2 else 0.0   
        if requested_target is not None and torch.abs(target-requested_target) > 1e-3: 
            raise UserWarning(f"Warning: requested_target = {requested_target}, but got target = {target}")
        # --- Now we know what shifts we want to do, next let's construct the crops.

        # obtain the wider anchor, with sufficient padding later crops
        pad_x = ( abs(min(min(dx1,dx2), 0)), max(max(dx1, dx2), 0) ) 
        anchor = super().__getitem__(idx, pad_x=pad_x)
        img = anchor['img']  # (1, H, crop_size + 2*sx)  <-- note the extra "1," for what follows!
        cs = self.crop_size if isinstance(self.crop_size, int) else self.crop_size[1]  # width dimension

        # crops in x
        c1 = img[:,:, pad_x[0]+dx1: pad_x[0]+dx1+cs]
        c2 = img[:,:, pad_x[0]+dx2: pad_x[0]+dx2+cs]
        img = img[:,:,pad_x[0]:     pad_x[0]+cs]       # crop anchor to final size

        # shift c1 and c2 images in y 
        c1 = shift_no_wrap(c1, shifts=dy1, dims=1) 
        c2 = shift_no_wrap(c2, shifts=dy2, dims=1)
        return {
            'img1': img, 'img2': c1, 'img3': c2,
            'deltas': torch.tensor([[dy1,dx1],[dy2,dx2]], dtype=torch.int),
            'file_idx': anchor['file_idx'], 'scheme': scheme, 'target': torch.tensor(target),
        }

# %% ../nbs/01_data.ipynb #510bad1c
class PreEncodedChunkDataset(Dataset):
    """Lazy-loading dataset for preencode chunk files (list-of-batch-dicts format).
    Each chunk is a list of dicts with emb keys (list of level tensors, each (B,N,D))
    and optionally img keys ((B,C,H,W) bool). Flattens to individual samples.

    Args:
        encoded_dir: directory containing {split}_chunk*.pt files
        split:       'train' or 'val'
        emb_key:     which embedding to return ('emb1', 'emb2', 'emb3')
        img_key:     which image to return ('img1', etc.), or None to omit images

    Returns (emb_levels, img) tuples, or just emb_levels when img_key=None."""
    def __init__(self, encoded_dir, split='train', emb_key='emb1', img_key='img1'):
        self.emb_key, self.img_key = emb_key, img_key
        self.files = sorted(glob(os.path.join(encoded_dir, f'{split}_chunk*.pt')))
        assert self.files, f"No {split}_chunk*.pt files in {encoded_dir}"
        self.index = []
        self.chunk_sample_ranges = {}
        for ci, f in enumerate(self.files):
            chunk = torch.load(f, map_location='cpu', weights_only=False)
            start = len(self.index)
            for ri, rec in enumerate(chunk):
                for si in range(rec[emb_key][0].shape[0]):
                    self.index.append((ci, ri, si))
            self.chunk_sample_ranges[ci] = (start, len(self.index))
            del chunk
        self._cache_ci = None
        self._cache_data = None

    def __len__(self): return len(self.index)

    def __getitem__(self, idx):
        ci, ri, si = self.index[idx]
        if ci != self._cache_ci:
            self._cache_data = torch.load(self.files[ci], map_location='cpu', weights_only=False)
            self._cache_ci = ci
        rec = self._cache_data[ri]
        emb = [lvl[si].float() for lvl in rec[self.emb_key]]
        if self.img_key is None: return emb
        return emb, rec[self.img_key][si].float()


class ChunkShuffleSampler(Sampler):
    """Shuffle chunk order each epoch; access items within each chunk sequentially.
    Prevents DataLoader workers from thrashing between chunks."""
    def __init__(self, dataset, shuffle=True):
        self.dataset = dataset
        self.shuffle = shuffle

    def __len__(self): return len(self.dataset)

    def __iter__(self):
        n = len(self.dataset.files)
        order = torch.randperm(n).tolist() if self.shuffle else list(range(n))
        indices = []
        for ci in order:
            s, e = self.dataset.chunk_sample_ranges[ci]
            indices.extend(range(s, e))
        return iter(indices)


def collate_emb_levels(batch):
    "Stack per-sample level embeddings (list of (N,D) tensors), padding variable-N to max."
    n_levels = len(batch[0])
    result = []
    for lev in range(n_levels):
        tensors = [item[lev] for item in batch]
        max_n = max(t.shape[0] for t in tensors)
        padded = []
        for t in tensors:
            if t.shape[0] < max_n:
                t = torch.cat([t, torch.zeros(max_n - t.shape[0], *t.shape[1:], dtype=t.dtype)], 0)
            padded.append(t)
        result.append(torch.stack(padded))
    return result


def collate_preencode(batch):
    "Collate (emb_levels, img) pairs from PreEncodedChunkDataset."
    return collate_emb_levels([b[0] for b in batch]), torch.stack([b[1] for b in batch])


def get_pos_cache(encoder, image_size, device):
    "Run encoder on a dummy input to extract the fixed per-level positional grid."
    dummy = torch.zeros(1, 1, image_size, image_size, device=device)
    with torch.no_grad():
        enc_out = encoder(dummy)
    return [lvl.pos.squeeze(0) for lvl in enc_out.patches.levels]


def emb_levels_to_enc_out(emb_levels, pos_cache, device):
    "Assemble a minimal EncoderOutput from stored emb level tensors and a pos cache."
    levels = [PatchState(emb=emb.to(device), pos=pos_cache[i], non_empty=None, mae_mask=None)
              for i, emb in enumerate(emb_levels)]
    return EncoderOutput(patches=HierarchicalPatchState(levels=levels),
                         full_pos=None, full_non_empty=None, mae_mask=None)


# ---------------------------------------------------------------------------
# NOTE: everything below this point is HAND-WRITTEN (not exported from nbs/01_data.ipynb).
# It supports training on the full MuseScore-big-MIDI dataset (~1M files) via
# lazily-loaded sharded piano-roll tensors instead of loading every PNG into RAM.
# See scripts/midi_to_pianoroll.py for how shards are produced.
# Running `nbdev_prepare` will overwrite this file from the notebook and DROP these
# classes -- port them into nbs/01_data.ipynb before doing that.
# ---------------------------------------------------------------------------

class _ShardCache:
    "1-slot cache so sequential (shard-shuffled) access doesn't reload a shard per sample."
    def __init__(self):
        self.idx, self.data = None, None
    def get(self, shard_paths, i):
        if self.idx != i:
            self.data = torch.load(shard_paths[i], map_location='cpu', weights_only=False)
            self.idx = i
        return self.data


def _build_shard_index(shard_dir, split):
    "Build a (shard_idx, record_idx) index from small sidecar .idx.json files (no big tensor loads)."
    shard_paths = sorted(glob(os.path.join(os.path.expanduser(shard_dir), f'{split}_shard*.pt')))
    assert shard_paths, f"No {split}_shard*.pt files found in {shard_dir}"
    index, ranges = [], {}
    for si, sp in enumerate(shard_paths):
        idx_path = sp.replace('.pt', '.idx.json')
        with open(idx_path) as f:
            n = json.load(f)['count']
        start = len(index)
        index.extend((si, ri) for ri in range(n))
        ranges[si] = (start, len(index))
    return shard_paths, index, ranges


class ShardedAnchorDataset(Dataset):
    """Lazy-loading, disk-backed equivalent of AnchorDataset for large-scale MIDI sets.
    Backed by sharded .pt files of uint8 (128, T) binary piano-roll arrays.
    Use with ChunkShuffleSampler so DataLoader workers visit one shard at a time.
    """
    def __init__(self, shard_dir, crop_size=128, split='train', verbose=True,
                 aug_y_max=12, sigma=7, pad_x=(0, 0)):
        self.crop_size = (crop_size, crop_size) if isinstance(crop_size, int) else crop_size
        self.aug_y_max, self.sigma, self.pad_x = aug_y_max, sigma, pad_x
        self.files, self.index, self.chunk_sample_ranges = _build_shard_index(shard_dir, split)
        self._cache = _ShardCache()
        if verbose:
            print(f"ShardedAnchorDataset[{split}]: {len(self.files)} shards, {len(self.index)} records")

    def __len__(self): return len(self.index)

    def _get_array(self, idx):
        si, ri = self.index[idx]
        shard = self._cache.get(self.files, si)
        return shard[ri]  # uint8 numpy (128, T)

    def __getitem__(self, idx, pad_x=None, crop_size=None):
        if crop_size is None: crop_size = self.crop_size
        if isinstance(crop_size, int): crop_size = (crop_size, crop_size)
        if pad_x is None: pad_x = self.pad_x

        arr = self._get_array(idx)
        img = torch.from_numpy(arr.astype(np.float32))
        h, w = img.shape
        need = crop_size[1] + pad_x[0] + pad_x[1]
        if w < need + 1:  # pad short pieces so a valid crop location always exists
            img = torch.cat([img, torch.zeros(h, need + 1 - w)], dim=1)
            w = img.shape[1]

        aug_y = sample_shift(self.aug_y_max, self.sigma)
        img = shift_no_wrap(img, shifts=aug_y, dims=0)

        min_loc, max_loc = 0 + pad_x[0], w - crop_size[1] - pad_x[1]
        loc = random.randint(min_loc, max_loc)
        img = img[:, loc - pad_x[0]: loc + crop_size[1] + pad_x[1]]

        if crop_size[0] < img.shape[0]:
            mid, hc = img.shape[0] // 2, crop_size[0] // 2
            img = img[mid - hc: mid + hc, :]

        note_weights = torch.from_numpy(note_length_weights(img.numpy()).astype(np.float16))
        return {
            'img': img.unsqueeze(0),
            'file_idx': idx,
            'note_weights': note_weights.unsqueeze(0),
        }


class ShardedTripletDataset(ShardedAnchorDataset):
    """Lazy-loading, disk-backed equivalent of ShiftedTripletDataset (pitch/time factorization
    triplets) for large-scale MIDI sets. Same augmentation math as ShiftedTripletDataset,
    just sourcing the base image from a shard instead of an in-RAM list."""
    def __init__(self, shard_dir, max_shift_x=12, max_shift_y=12, shared=None, aug_y_max=6, **kwargs):
        super().__init__(shard_dir, aug_y_max=aug_y_max, **kwargs)
        self.max_shift_x, self.max_shift_y, self.shared = max_shift_x, max_shift_y, shared

    def __getitem__(self, idx, requested_scheme=None, requested_target=None):
        msx = self.shared['training']['max_shift_x'] if self.shared else self.max_shift_x
        msy = self.shared['training']['max_shift_y'] if self.shared else self.max_shift_y
        while True:
            scheme = torch.randint(0, 3, (1,)).item() if requested_scheme is None else int(requested_scheme)
            if requested_target is not None and requested_target != 0: scheme = torch.randint(0, 2, (1,)).item()
            sign1 = 1 if torch.rand(1) > 0.5 else -1
            if requested_target is None:
                sign2 = 1 if torch.rand(1) > 0.5 else -1
            else:
                sign2 = sign1 * int(requested_target)
            if scheme == 0:
                s1 = abs(sample_shift(msy, self.sigma)) or 1
                s2 = abs(sample_shift(msy, self.sigma)) or 1
                dy1, dx1, dy2, dx2 = sign1*s1, 0, sign2*s2, 0
            elif scheme == 1:
                s1 = abs(sample_shift(msx, self.sigma)) or 1
                s2 = abs(sample_shift(msx, self.sigma)) or 1
                dy1, dx1, dy2, dx2 = 0, sign1*s1, 0, sign2*s2
            else:
                s1 = abs(sample_shift(msy, self.sigma)) or 1
                s2 = abs(sample_shift(msx, self.sigma)) or 1
                dy1, dx1, dy2, dx2 = sign1*s1, 0, 0, sign2*s2
            if not ((dy1 == dy2) and (dx1 == dx2)) and not (dx1 == 0 and dy1 == 0) and not (dx2 == 0 and dy2 == 0): break
        target = float(np.sign(sign1 * sign2)) if scheme < 2 else 0.0

        pad_x = (abs(min(min(dx1, dx2), 0)), max(max(dx1, dx2), 0))
        anchor = super().__getitem__(idx, pad_x=pad_x)
        img = anchor['img']
        cs = self.crop_size[1]

        c1 = img[:, :, pad_x[0] + dx1: pad_x[0] + dx1 + cs]
        c2 = img[:, :, pad_x[0] + dx2: pad_x[0] + dx2 + cs]
        img = img[:, :, pad_x[0]: pad_x[0] + cs]

        c1 = shift_no_wrap(c1, shifts=dy1, dims=1)
        c2 = shift_no_wrap(c2, shifts=dy2, dims=1)
        return {
            'img1': img, 'img2': c1, 'img3': c2,
            'deltas': torch.tensor([[dy1, dx1], [dy2, dx2]], dtype=torch.int),
            'file_idx': anchor['file_idx'], 'scheme': scheme, 'target': torch.tensor(target),
        }

